import{prepareAjuRegion}from'./provider.mjs';import{AJU}from'./registration.mjs';
const MANIFEST_SHA='3f337223b51724f825810ff0a15a6eecbb02897a1202f836342f35a9272ff4cc',direction={down:'FRONT',right:'RIGHT',left:'LEFT',up:'BACK'},hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function prepareAjuPresentation({signal,appearance='boy',fetcher=fetch,decode=b=>createImageBitmap(new Blob([b],{type:'image/png'})),canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}={}){
 if(!['boy','girl'].includes(appearance))throw Error('AJU_APPEARANCE');let disposed=false,provider,native,lastFrame=null,lastPose=null,lastState=null;const images=new Map,actorCanvases=new Map;const check=()=>{if(disposed||signal?.aborted)throw Error('AJU_PRESENTATION_ABORT')};const dispose=()=>{if(disposed)return;disposed=true;lastFrame=lastPose=lastState=null;signal?.removeEventListener('abort',dispose);provider?.dispose();for(const im of images.values())im.close?.();images.clear();for(const c of actorCanvases.values())c.width=c.height=1;actorCanvases.clear();if(native)native.width=native.height=1;native=null};
 const read=async(url,pin)=>{check();const res=await fetcher(url,{signal});if(!res.ok)throw Error('AJU_ATLAS_HTTP');const b=(await res.arrayBuffer()).slice(0);if(await hash(b)!==pin)throw Error('AJU_ATLAS_PIN');check();return b};
 try{provider=await prepareAjuRegion({signal,fetcher,decode,canvasFactory});const manifest=JSON.parse(new TextDecoder().decode(await read(new URL('../../assets/approved-atlases/manifest.json',import.meta.url),MANIFEST_SHA))),playerId=appearance==='girl'?'PLAYER_FEMALE':'PLAYER_MALE';
 for(const key of new Set([...AJU.actors.map(a=>'npc/'+a.sprite),'player/'+playerId])){const pin=manifest.atlases[key],im=await decode(await read(new URL('../../'+pin.src,import.meta.url),pin.sha256));images.set(key,im);check()}
 native=canvasFactory(960,540);check();signal?.addEventListener('abort',dispose,{once:true});
 function pack(id,key,kind,foot,facing,step){const frame=manifest.frames[kind][`${key}.${direction[facing]}.${step}`];if(!frame)throw Error('AJU_FRAME');let c=actorCanvases.get(id);if(!c){c=canvasFactory(frame.width,frame.height);actorCanvases.set(id,c)}c.width=frame.width;c.height=frame.height;const g=c.getContext('2d');g.drawImage(images.get(frame.atlas),...frame.rect,0,0,frame.width,frame.height);const sc=80/192;return{image:c,foot,origin:[foot[0]-frame.anchor[0]*sc,foot[1]-frame.anchor[1]*sc],width:frame.width*sc,height:frame.height*sc}}
 function draw(destination,{foot,facing,elapsedMs=0,moving=false,nightMix=0,lightsEnabled=true,npcFacings={},windRest=false,windEnabled=true}={}){lastFrame=lastPose=lastState=null;if(disposed)return false;check();const pose=provider.describe(foot,facing),w=destination.canvas.width,h=destination.canvas.height,cx=Math.floor(Math.max(0,Math.min(1536-w,foot[0]-w/2))),cy=Math.floor(Math.max(0,Math.min(1024-h,foot[1]-h/2)));if(!Number.isFinite(elapsedMs)||elapsedMs<0)throw Error('AJU_TIME');native.width=w;native.height=h;const actors=AJU.actors.filter(a=>a.foot[0]>=cx-100&&a.foot[0]<cx+w+100&&a.foot[1]>=cy-100&&a.foot[1]<cy+h+100).map(a=>pack(a.id,a.sprite,'npc',a.foot,direction[npcFacings[a.id]]?npcFacings[a.id]:a.facing,'IDLE'));actors.push(pack('player',playerId,'player',[...foot],facing,moving?['A','IDLE','B','IDLE'][Math.floor(elapsedMs/140)%4]:'IDLE'));if(!provider.draw(native.getContext('2d'),{camera:[cx,cy,w,h],actors,elapsedMs,nightMix,moving,windEnabled,windRest,lightsEnabled}))return false;destination.save();try{destination.imageSmoothingEnabled=false;destination.clearRect(0,0,w,h);destination.drawImage(native,0,0)}finally{destination.restore()}lastPose=pose;lastState={elapsedMs,nightMix,moving,lightsEnabled,windEnabled,windRest};lastFrame=Object.freeze({});return true}
 const frameMatchesPose=(token,pose)=>!disposed&&!!lastFrame&&token===lastFrame&&provider.validate(pose)&&pose.foot[0]===lastPose.foot[0]&&pose.foot[1]===lastPose.foot[1]&&pose.facing===lastPose.facing;
 return Object.freeze({registration:AJU,requestWindFrame:ms=>{check();return provider.requestWindFrame(ms)},windPacketStats:()=>provider.windPacketStats(),frameMatchesState:(token,pose,state)=>frameMatchesPose(token,pose)&&!!state&&['elapsedMs','nightMix','moving','lightsEnabled','windEnabled','windRest'].every(k=>Object.getOwnPropertyDescriptor(state,k)?.value===lastState[k]),get pinsVerified(){return!disposed},currentFrame:()=>lastFrame,frameMatchesPose,safe:provider.safe,validate:provider.validate,describe:provider.describe,contact:provider.contact,resolveContact:provider.resolveContact,wildZone:provider.wildZone,noteStep:(...a)=>{check();lastFrame=lastPose=lastState=null;return provider.noteStep(...a)},resetContact:()=>{check();lastFrame=lastPose=lastState=null;provider.resetContact()},draw,dispose});
 }catch(e){dispose();throw e}
}
